display.text:
import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import CitizenPortal from './components/CitizenPortal';
import AdminDashboard from './components/AdminDashboard';
import TrackStatus from './components/TrackStatus';
import ComplaintDetailsModal from './components/ComplaintDetailsModal';
import Footer from './components/Footer';
import { initialComplaints } from './data/initialData';

export default function App() {
  const [activeTab, setActiveTab] = useState('citizen');
  const [currentLang, setCurrentLang] = useState('en');
  const [selectedTrackId, setSelectedTrackId] = useState('');
  const [modalComplaint, setModalComplaint] = useState(null);
  const [toastMessage, setToastMessage] = useState(null);

  const [complaints, setComplaints] = useState(() => {
    const saved = localStorage.getItem('prajasolve_complaints');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to parse localStorage complaints', e);
      }
    }
    return initialComplaints;
  });

  useEffect(() => {
    localStorage.setItem('prajasolve_complaints', JSON.stringify(complaints));
  }, [complaints]);

  const triggerToast = (msg, type = 'success') => {
    setToastMessage({ text: msg, type });
    setTimeout(() => {
      setToastMessage(null);
    }, 4000);
  };

  const handleAddComplaint = (newComplaint) => {
    setComplaints((prev) => [newComplaint, ...prev]);
    triggerToast(`Grievance #${newComplaint.id} submitted & auto-routed!`);
  };

  const handleUpdateStatus = (id, newStatus) => {
    setComplaints((prev) =>
      prev.map((c) => (c.id === id ? { ...c, status: newStatus } : c))
    );
    triggerToast(`Grievance ${id} status updated to "${newStatus}"`);
  };

  return (
    <div className="min-h-screen bg-pink-50/40 text-slate-800 flex flex-col justify-between selection:bg-pink-500 selection:text-white">

      {/* Toast Notification Banner */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 animate-bounce">
          <div className="bg-pink-600 text-white px-5 py-3 rounded-2xl shadow-2xl shadow-pink-500/30 flex items-center gap-3 text-sm font-semibold border border-pink-400">
            <span className="w-2.5 h-2.5 rounded-full bg-white animate-ping"></span>
            <span>{toastMessage.text}</span>
          </div>
        </div>
      )}

      {/* Navigation Header */}
      <Navbar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        currentLang={currentLang}
        setCurrentLang={setCurrentLang}
        totalComplaints={complaints.length}
      />

      {/* Main View Switcher */}
      <main className="flex-grow">
        {activeTab === 'citizen' && (
          <CitizenPortal
            onAddComplaint={handleAddComplaint}
            currentLang={currentLang}
            setActiveTab={setActiveTab}
            setSelectedTrackId={setSelectedTrackId}
          />
        )}

        {activeTab === 'track' && (
          <TrackStatus
            complaints={complaints}
            initialSearchId={selectedTrackId}
            currentLang={currentLang}
          />
        )}

        {activeTab === 'admin' && (
          <AdminDashboard
            complaints={complaints}
            onUpdateStatus={handleUpdateStatus}
            onViewDetails={(item) => setModalComplaint(item)}
            currentLang={currentLang}
          />
        )}
      </main>

      {/* Detail Modal */}
      {modalComplaint && (
        <ComplaintDetailsModal
          complaint={modalComplaint}
          onClose={() => setModalComplaint(null)}
          onUpdateStatus={handleUpdateStatus}
          currentLang={currentLang}
        />
      )}

      {/* Footer */}
      <Footer currentLang={currentLang} setActiveTab={setActiveTab} />
    </div>
  );
}

