import React, { useState } from 'react';
import { 
  Building2, 
  FileText, 
  Search, 
  ShieldCheck, 
  Globe, 
  Menu, 
  X,
  Sparkles,
  Zap
} from 'lucide-react';
import { translations } from '../data/translations';

export default function Navbar({ activeTab, setActiveTab, currentLang, setCurrentLang, totalComplaints }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const t = translations[currentLang] || translations.en;

  const handleTabChange = (tabId) => {
    setActiveTab(tabId);
    setMobileMenuOpen(false);
  };

  return (
    <header className="sticky top-0 z-50 glass-panel-light border-b border-pink-100 shadow-sm backdrop-blur-xl">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-20">

          {/* Logo & Tagline */}
          <div 
            className="flex items-center gap-3 cursor-pointer group"
            onClick={() => handleTabChange('citizen')}
          >
            <div className="relative">
              <div className="w-12 h-12 rounded-2xl bg-gradient-to-tr from-pink-600 via-rose-500 to-pink-400 flex items-center justify-center text-white shadow-lg shadow-pink-500/25 group-hover:scale-105 transition-transform duration-300">
                <Building2 className="w-6 h-6" />
              </div>
            </div>

            <div>
              <div className="flex items-center gap-2">
                <span className="text-2xl font-extrabold tracking-tight text-slate-900 font-sans">
                  Praja<span className="text-pink-600">Solve</span>
                </span>
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold bg-pink-100 text-pink-700 border border-pink-200">
                  <Sparkles className="w-3 h-3 text-pink-600" /> AI
                </span>
              </div>
              <p className="text-xs text-pink-700 font-semibold tracking-wide">
                {t.tagline}
              </p>
            </div>
          </div>

          {/* Desktop Navigation Links */}
          <nav className="hidden md:flex items-center gap-1 bg-pink-100/60 p-1.5 rounded-2xl border border-pink-200">
            <button
              onClick={() => handleTabChange('citizen')}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium transition-all duration-200 ${
                activeTab === 'citizen'
                  ? 'bg-gradient-to-r from-pink-600 to-rose-600 text-white shadow-md shadow-pink-500/20 font-bold'
                  : 'text-slate-700 hover:text-pink-700 hover:bg-white/60'
              }`}
            >
              <FileText className="w-4 h-4" />
              {t.navSubmit}
            </button>

            <button
              onClick={() => handleTabChange('track')}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium transition-all duration-200 ${
                activeTab === 'track'
                  ? 'bg-gradient-to-r from-pink-600 to-rose-600 text-white shadow-md shadow-pink-500/20 font-bold'
                  : 'text-slate-700 hover:text-pink-700 hover:bg-white/60'
              }`}
            >
              <Search className="w-4 h-4" />
              {t.navTrack}
            </button>

            <button
              onClick={() => handleTabChange('admin')}
              className={`relative flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium transition-all duration-200 ${
                activeTab === 'admin'
                  ? 'bg-gradient-to-r from-pink-600 to-rose-600 text-white shadow-md shadow-pink-500/20 font-bold'
                  : 'text-slate-700 hover:text-pink-700 hover:bg-white/60'
              }`}
            >
              <ShieldCheck className="w-4 h-4 text-pink-600" />
              {t.navAdmin}
              {totalComplaints > 0 && (
                <span className="ml-1 px-1.5 py-0.2 rounded-full text-xs font-bold bg-pink-600 text-white">
                  {totalComplaints}
                </span>
              )}
            </button>
          </nav>

          {/* Right Section: Language Switcher */}
          <div className="hidden lg:flex items-center gap-4">
            <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-xl border border-pink-200 shadow-sm">
              <Globe className="w-4 h-4 text-pink-600" />
              <select
                value={currentLang}
                onChange={(e) => setCurrentLang(e.target.value)}
                className="bg-transparent text-sm text-slate-700 font-semibold focus:outline-none cursor-pointer pr-2"
                aria-label="Language Selector"
              >
                <option value="en">English (EN)</option>
                <option value="te">తెలుగు (TE)</option>
                <option value="hi">हिंदी (HI)</option>
              </select>
            </div>

            <div className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-pink-100 border border-pink-200 text-pink-800 text-xs font-bold">
              <Zap className="w-3.5 h-3.5 fill-current text-pink-600" />
              <span>NLP AI Online</span>
            </div>
          </div>

          {/* Mobile Menu Button */}
          <div className="flex items-center gap-2 md:hidden">
            <div className="flex items-center bg-white px-2 py-1 rounded-lg border border-pink-200 text-xs">
              <Globe className="w-3.5 h-3.5 text-pink-600 mr-1" />
              <select
                value={currentLang}
                onChange={(e) => setCurrentLang(e.target.value)}
                className="bg-transparent text-xs text-slate-700 font-bold focus:outline-none cursor-pointer"
                aria-label="Mobile Language Selector"
              >
                <option value="en">EN</option>
                <option value="te">TE</option>
                <option value="hi">HI</option>
              </select>
            </div>

            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="p-2 rounded-xl text-slate-700 hover:bg-pink-100 focus:outline-none"
              aria-label="Toggle Mobile Menu"
            >
              {mobileMenuOpen ? <X className="w-6 h-6 text-pink-700" /> : <Menu className="w-6 h-6 text-pink-700" />}
            </button>
          </div>

        </div>
      </div>

      {/* Mobile Drawer */}
      {mobileMenuOpen && (
        <div className="md:hidden glass-panel-light border-b border-pink-200 px-4 pt-2 pb-6 space-y-2 animate-fade-in">
          <button
            onClick={() => handleTabChange('citizen')}
            className={`w-full flex items-center justify-between p-3 rounded-xl text-sm font-semibold transition-all ${
              activeTab === 'citizen' ? 'bg-pink-600 text-white' : 'text-slate-700 hover:bg-pink-50'
            }`}
          >
            <span className="flex items-center gap-2">
              <FileText className="w-4 h-4" />
              {t.navSubmit}
            </span>
          </button>

          <button
            onClick={() => handleTabChange('track')}
            className={`w-full flex items-center justify-between p-3 rounded-xl text-sm font-semibold transition-all ${
              activeTab === 'track' ? 'bg-pink-600 text-white' : 'text-slate-700 hover:bg-pink-50'
            }`}
          >
            <span className="flex items-center gap-2">
              <Search className="w-4 h-4" />
              {t.navTrack}
            </span>
          </button>

          <button
            onClick={() => handleTabChange('admin')}
            className={`w-full flex items-center justify-between p-3 rounded-xl text-sm font-semibold transition-all ${
              activeTab === 'admin' ? 'bg-pink-600 text-white' : 'text-slate-700 hover:bg-pink-50'
            }`}
          >
            <span className="flex items-center gap-2">
              <ShieldCheck className="w-4 h-4" />
              {t.navAdmin}
            </span>
            <span className="px-2 py-0.5 rounded-full text-xs bg-pink-100 text-pink-800 font-bold">
              {totalComplaints}
            </span>
          </button>
        </div>
      )}
    </header>
  );
}

