// =========================================================================
function App() {
  const [currentLang, setCurrentLang] = useState(localStorage.getItem('prajasolve_lang') || 'en');
  const [user, setUser] = useState(null);
  const [sessionLoading, setSessionLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('home');
  const [selectedTrackId, setSelectedTrackId] = useState('');
  const [toast, setToast] = useState(null);
  const [notifs, setNotifs] = useState([]);
  const [refreshKey, setRefreshKey] = useState(0);

  const t = useMemo(() => Object.assign({}, translations.en, translations[currentLang] || {}), [currentLang]);

  useEffect(() => { localStorage.setItem('prajasolve_lang', currentLang); }, [currentLang]);

  useEffect(() => {
    (async () => {
      const token = localStorage.getItem('prajasolve_token');
      if (!token) { setSessionLoading(false); return; }
      try {
        const data = await api('/api/auth/me');
        if (data.success) {
          setUser(data.user);
          setActiveTab(data.user.role === 'officer' ? 'officer' : 'dashboard');
        } else {
          localStorage.removeItem('prajasolve_token');
        }
      } catch (err) {
        if (err.status === 401) localStorage.removeItem('prajasolve_token');
      } finally {
        setSessionLoading(false);
      }
    })();
  }, []);

  const loadNotifs = useCallback(async () => {
    try {
      const data = await api('/api/notifications');
      if (data.success) setNotifs(data.notifications);
    } catch (err) { /* ignore */ }

