const fs = require("fs");
const babel = require("@babel/core");
const { JSDOM } = require("jsdom");

const htmlPath = "C:/Users/pbhav/OneDrive/Documents/ppt/index.html";
const html = fs.readFileSync(htmlPath, "utf8");
const marker = '<script type="text/babel">';
const start = html.indexOf(marker);
const innerStart = start + marker.length;
const end = html.indexOf("</script>", innerStart);
const code = html.slice(innerStart, end);

const compiled = babel.transformSync(code, {
  filename: "app.jsx",
  presets: [
    ["@babel/preset-env", { targets: { chrome: "90" }, modules: "commonjs" }],
    ["@babel/preset-react", { runtime: "classic" }],
  ],
}).code;

const EMAIL = "officer@civic.gov.in";
const PASS = "Officer@123";

(async () => {
  const loginRes = await fetch("http://127.0.0.1:5000/api/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: EMAIL, password: PASS }),
  });
  const token = (await loginRes.json()).token;
  console.log("officer token acquired:", !!token);

  const dom = new JSDOM("<!doctype html><html><body><div id='root'></div></body></html>", {
    url: "http://127.0.0.1:5000/",
    pretendToBeVisual: true,
  });
  const { window } = dom;
  window.localStorage.setItem("prajasolve_token", token);

  const realFetch = global.fetch;
  const resolveFetch = (url, opts) => realFetch(new URL(String(url), "http://127.0.0.1:5000/").toString(), opts);
  window.fetch = resolveFetch;
  window.speechSynthesis = { speak() {}, cancel() {}, getVoices: () => [] };
  window.SpeechRecognition = undefined;
  window.webkitSpeechRecognition = undefined;

  global.window = window;
  global.document = window.document;
  global.navigator = window.navigator;
  global.localStorage = window.localStorage;
  global.fetch = resolveFetch;
  global.React = require("react");
  const ReactDOMClient = require("react-dom/client");
  global.ReactDOM = Object.assign({}, require("react-dom"), ReactDOMClient);
  global.speechSynthesis = window.speechSynthesis;

  const errors = [];
  window.onerror = (msg) => errors.push("window.onerror: " + msg);
  process.on("unhandledRejection", (r) => errors.push("unhandledRejection: " + (r && r.message)));

  try {
    new Function("React", "ReactDOM", "window", "document", "localStorage", compiled)(React, ReactDOM, window, document, localStorage);
  } catch (e) {
    console.log("RUNTIME THROW:", e.message);
    process.exit(2);
  }

  await new Promise((r) => setTimeout(r, 1500));
  const text = document.getElementById("root").innerHTML;
  console.log("root length:", text.length);
  console.log("OfficerDashboard rendered (Set status):", text.includes("Set status to"));
  console.log("officer filter/search present:", text.includes("Search") || text.includes("Filter"));
  console.log("stats cards present:", text.includes("Resolved"));
  if (errors.length) {
    console.log("ERRORS:");
    errors.forEach((e) => console.log(" -", e));
    process.exit(3);
  }
  console.log(text.length > 500 ? "OFFICER RENDER OK" : "OFFICER RENDER EMPTY");
})().catch((e) => {
  console.log("HARNESS FAILED:", e.message);
  process.exit(2);
});

