function clickByText(window, text) {
  const els = Array.from(window.document.querySelectorAll("button, a, span, div"));
  const el = els.find((e) => e.textContent && e.textContent.trim() === text && e.offsetParent !== null);
  if (!el) return false;
  const evt = new window.MouseEvent("click", { bubbles: true, cancelable: true });
  el.dispatchEvent(evt);
  return true;
}

function setInput(window, name, value) {
  const el = window.document.querySelector(`input[name="${name}"], textarea[name="${name}"], select[name="${name}"]`);
  if (!el) return false;
  const proto = el.tagName === "SELECT" ? window.HTMLSelectElement.prototype : (el.tagName === "TEXTAREA" ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype);
  const setter = Object.getOwnPropertyDescriptor(proto, "value").set;
  setter.call(el, value);
  el.dispatchEvent(new window.Event("input", { bubbles: true }));
  el.dispatchEvent(new window.Event("change", { bubbles: true }));
  return true;
}

