        : [{ id: 'file', label: t.navFile }, { id: 'track', label: t.navTrack }, { id: 'dashboard', label: t.navDashboard }, { id: 'home', label: t.navHome }])
    : [{ id: 'home', label: t.navHome }, { id: 'track', label: t.navTrack }, { id: 'auth', label: t.loginBtn }];

