function CitizenForm({ t, currentLang, onNewComplaint, onAuthError, onTrack, triggerToast }) {
  const [form, setForm] = useState({ title: '', description: '', category: '', location: '' });
  const [imageData, setImageData] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [error, setError] = useState('');
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState(null);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (!/^image\/(png|jpe?g|webp|gif)$/.test(file.type)) {
      setError(t.errCategory); // generic: unsupported type shown by backend too
      triggerToast('⚠️ JPG/PNG/WEBP/GIF only', 'error');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      triggerToast('⚠️ Max 5 MB', 'error');
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setImageData(reader.result);
      setImagePreview(reader.result);
    };
    reader.readAsDataURL(file);
  };

  const validate = () => {
    if (form.title.trim().length < 4) return t.errTitle;
    if (form.description.trim().length < 10) return t.errDesc;
    if (!form.category) return t.errCategory;
    if (form.location.trim().length < 3) return t.errLocation;
    return '';
  };

  const submit = async (e) => {
    e.preventDefault();
    const verr = validate();
    if (verr) { setError(verr); return; }
    setError('');
    setAnalyzing(true);
    try {
      const [data] = await Promise.all([
        api('/api/complaints', 'POST', {
          title: form.title.trim(),
          description: form.description.trim(),
          category: form.category,
          location: form.location.trim(),
          imageData: imageData || null
        }),
        delay(1800)
      ]);
      if (data.success) {
        setResult(data.complaint);
        onNewComplaint();
        triggerToast(t.successMsg);
      }
    } catch (err) {
      if (err.status === 401) { onAuthError(err); }
      else { setError((err.data && err.data.error) || t.submitFailed); }
    } finally {
      setAnalyzing(false);
    }
  };

  const categories = [
    { v: 'Roads', l: t.catRoads }, { v: 'Garbage', l: t.catGarbage }, { v: 'Water Supply', l: t.catWater },
    { v: 'Streetlights', l: t.catStreetlights }, { v: 'Drainage', l: t.catDrainage },
    { v: 'Electricity', l: t.catElectricity }, { v: 'Public Safety', l: t.catSafety }, { v: 'Other', l: t.catOther }
  ];

  if (analyzing) {
    return (
      <div className="max-w-2xl mx-auto glass-card-pink rounded-3xl p-10 sm:p-14 border border-pink-200 text-center shadow-2xl animate-fade-in">
        <div className="w-20 h-20 mx-auto rounded-3xl bg-gradient-to-tr from-pink-600 via-rose-500 to-pink-400 flex items-center justify-center text-white text-4xl shadow-lg shadow-pink-500/30">
          🤖
        </div>
        <h2 className="text-xl sm:text-2xl font-extrabold text-slate-900 mt-6 ai-analyzing">{t.analyzingMsg}</h2>
        <div className="flex items-center justify-center gap-1.5 mt-6">
          <span className="w-2.5 h-2.5 rounded-full bg-pink-500 animate-bounce"></span>
          <span className="w-2.5 h-2.5 rounded-full bg-rose-500 animate-bounce" style={{ animationDelay: '0.15s' }}></span>
          <span className="w-2.5 h-2.5 rounded-full bg-pink-400 animate-bounce" style={{ animationDelay: '0.3s' }}></span>
        </div>
      </div>
    );
  }

  if (result) {
    return (
      <div className="max-w-3xl mx-auto space-y-6 animate-fade-in">
        <div className="glass-card-pink rounded-3xl p-6 sm:p-10 border border-pink-300 space-y-6 shadow-2xl">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 pb-4 border-b border-pink-200">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-2xl bg-emerald-100 border border-emerald-300 text-emerald-700 flex items-center justify-center text-xl font-bold">✓</div>
              <div>
                <h2 className="text-xl font-bold text-slate-900">{t.resultTitle}</h2>
                <p className="text-xs text-emerald-700 font-semibold">{t.resultSub}</p>
              </div>
            </div>
            <div className="px-4 py-2 rounded-2xl bg-white border border-pink-200 text-right shadow-sm">
              <span className="text-xs text-slate-500 block">{t.compId}</span>
              <span className="text-lg font-mono font-extrabold text-pink-600">{result.complaint_id}</span>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="p-4 rounded-2xl bg-white border border-pink-200 space-y-1 shadow-sm">
              <span className="text-xs text-slate-500 block">🌐 {t.detLang}</span>
              <span className="text-sm font-bold text-slate-900">{result.ai_analysis ? result.ai_analysis.detectedLanguage : '-'}</span>
            </div>
            <div className="p-4 rounded-2xl bg-white border border-pink-200 space-y-1 shadow-sm">
              <span className="text-xs text-slate-500 block">🏷️ {t.cat}</span>
              <span className="text-sm font-bold text-slate-900">{result.category}</span>
            </div>
            <div className="p-4 rounded-2xl bg-white border border-pink-200 space-y-1 shadow-sm">
              <span className="text-xs text-slate-500 block">🏛️ {t.dept}</span>
              <span className="text-sm font-bold text-pink-700">{result.department}</span>

