const fs = require("fs");
const babel = require("@babel/core");
const { JSDOM } = require("jsdom");

const htmlPath = "C:/Users/pbhav/OneDrive/Documents/ppt/index.html";
const html = fs.readFileSync(htmlPath, "utf8");
const marker = '<script type="text/babel">';
const start = html.indexOf(marker);
const innerStart = start + marker.length;
const end = html.indexOf("</script>", innerStart);
const code = html.slice(innerStart, end);

const compiled = babel.transformSync(code, {
  filename: "app.jsx",
  presets: [
    ["@babel/preset-env", { targets: { chrome: "90" }, modules: "commonjs" }],
    ["@babel/preset-react", { runtime: "classic" }],
  ],
}).code;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function clickByText(window, text) {
  const els = Array.from(window.document.querySelectorAll("button, a"));
  const el = els.find((e) => e.textContent && e.textContent.trim() === text);
  if (!el) return false;
  el.dispatchEvent(new window.MouseEvent("click", { bubbles: true, cancelable: true }));
  return true;
}

function fillByPlaceholder(window, placeholder, value) {
  const el = Array.from(window.document.querySelectorAll("input, textarea"))
    .find((e) => e.getAttribute("placeholder") === placeholder);
  if (!el) return false;
  const proto = el.tagName === "TEXTAREA" ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype;
  const setter = Object.getOwnPropertyDescriptor(proto, "value").set;
  setter.call(el, value);
  el.dispatchEvent(new window.Event("input", { bubbles: true }));
  return true;
}

function setSelect(window, value) {
  const sel = window.document.querySelector("select");
  if (!sel) return false;
  const setter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, "value").set;
  setter.call(sel, value);
  sel.dispatchEvent(new window.Event("change", { bubbles: true }));
  return true;
}

(async () => {
  const loginRes = await fetch("http://127.0.0.1:5000/api/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: "demo@citizen.gov.in", password: "Demo@123" }),
  });
  const token = (await loginRes.json()).token;

  const dom = new JSDOM("<!doctype html><html><body><div id='root'></div></body></html>", {
    url: "http://127.0.0.1:5000/",
    pretendToBeVisual: true,
  });
  const { window } = dom;
  window.localStorage.setItem("prajasolve_token", token);

  const realFetch = global.fetch;
  const resolveFetch = (url, opts) => realFetch(new URL(String(url), "http://127.0.0.1:5000/").toString(), opts);
  window.fetch = resolveFetch;
  window.speechSynthesis = { speak() {}, cancel() {}, getVoices: () => [] };
  window.SpeechRecognition = undefined;
  window.webkitSpeechRecognition = undefined;

  global.window = window;
  global.document = window.document;
  global.navigator = window.navigator;
  global.localStorage = window.localStorage;
  global.fetch = resolveFetch;
  global.React = require("react");
  const ReactDOMClient = require("react-dom/client");
  global.ReactDOM = Object.assign({}, require("react-dom"), ReactDOMClient);
  global.speechSynthesis = window.speechSynthesis;

  const errors = [];
  window.onerror = (msg) => errors.push("window.onerror: " + msg);
  process.on("unhandledRejection", (r) => errors.push("unhandledRejection: " + (r && r.message)));

  try {
    new Function("React", "ReactDOM", "window", "document", "localStorage", compiled)(React, ReactDOM, window, document, localStorage);
  } catch (e) {
    console.log("RUNTIME THROW:", e.message);
    process.exit(2);
  }

  await sleep(1200);
  console.log("click File Grievance:", clickByText(window, "File Grievance"));
  await sleep(300);

  const title = "E2E Test Pothole " + Date.now();
  const desc = "A large pothole on the main road near the bus stop causing traffic and safety issues for commuters and pedestrians.";
  const filled = [
    fillByPlaceholder(window, "e.g. Large pothole near the school gate", title),
    fillByPlaceholder(window, "Describe the issue in detail (type or use the microphone)...", desc),
    fillByPlaceholder(window, "e.g. Kukatpally, Hyderabad", "Test Layout, Hyderabad"),
  ];
  console.log("fields filled:", filled);
  console.log("category selected:", setSelect(window, "Roads"));
  await sleep(200);

  const submitBtn = Array.from(window.document.querySelectorAll("button[type=submit]")).find((b) => b.textContent.trim() === "Submit Grievance");
  console.log("submit button found:", !!submitBtn);
  if (submitBtn) submitBtn.dispatchEvent(new window.MouseEvent("click", { bubbles: true, cancelable: true }));

  // wait for AI analyzing delay (1800ms) + api
  await sleep(4000);

  const text = document.getElementById("root").innerHTML;
  console.log("root length:", text.length);
  const idMatch = text.match(/GRV-2026-\d+/);
  console.log("complaint ID shown:", idMatch ? idMatch[0] : "NONE");
  console.log("result view rendered:", text.includes("complaint_id") || !!idMatch);
  if (errors.length) {
    console.log("ERRORS:");
    errors.forEach((e) => console.log(" -", e));
    process.exit(3);
  }
  console.log(idMatch ? "FULL SUBMISSION FLOW OK" : "SUBMISSION FAILED");
})().catch((e) => {
  console.log("HARNESS FAILED:", e.message);
  process.exit(2);
});

